import{c as t,Z as o,Q as r,j as i,m as n,o as s}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"相思","description":"","frontmatter":{"title":"相思","author":"王维","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/4.md","filePath":"books/shici/tangshi/4.md"}'),l={name:"books/shici/tangshi/4.md"};function h(c,a,d,p,u,_){const e=o("PoemNav");return r(),i("div",null,[a[0]||(a[0]=n('<h1 id="相思" tabindex="-1">相思 <a class="header-anchor" href="#相思" aria-label="Permalink to &quot;相思&quot;">​</a></h1><p><strong>[唐] <a href="/authors/wangwei.html">王维</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>红豆生南国，春来发几枝。 愿君多采撷，此物最相思。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>红豆：又名相思子，一种生在岭南地区的植物，结出的籽像豌豆而稍扁，呈鲜红色</li><li>南国：指岭南地区</li><li>采撷：采摘</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>红豆生长在阳光明媚的南方，春天来了它又生出多少新枝呢？希望你多多采摘一些红豆，因为它最能寄托人们的相思之情。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这是借咏物而寄相思的诗。起句因物起兴，语虽单纯，却富于想象；接着以设问寄语，意味深长；第三句暗示珍重友谊，表面似乎是嘱人相思，背面却深寓自身相思之重；结句点明主题。全诗情调健美高雅，怀思饱满奔放，语言朴素无华，韵律和谐柔美，可谓绝句的上乘之作。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>王维</strong>（701年－761年），字摩诘，号摩诘居士，唐代著名诗人、画家，与孟浩然并称“王孟”，有“诗佛”之称。其诗清新淡远，自然脱俗，苏轼赞其“诗中有画，画中有诗”。</p><p><a href="/authors/wangwei.html">查看作者详情 →</a></p></blockquote>',13)),s(e)])}const f=t(l,[["render",h]]);export{b as __pageData,f as default};
